{

    int outputId;
    str outputClass;
    str inputClass;
    int inputId;
}

Method.Source:
[DataMember('output_id')]
public int parmOutputId(int _outputId = outputId)
{
    outputId = _outputId;
    return outputId;
}

[DataMember('input_id')]
public int parmInputId(int _inputId = inputId)
{
    inputId = _inputId;
    return inputId;
}

[DataMember('output_class')]
public str parmOutputClass(str _output = outputClass)
{
